(7027363, 1065139, 19825, '<td valign="top">When this challenge was announced I am sure water tower ever crossed my mind as a possible subject. If it had, I could not have done nearly as nice a job as this. Bold choice and well executed.</td>', 'When this challenge was announced I am sure water tower ever crossed my mind as a possible subject. If it had, I could not have done nearly as nice a job as this. Bold choice and well executed.', '2013-04-26 10:55:24.000000', NULL, 0),
